`OptionalBool` = function(t)
{
  t = as.logical(t);
  ;ans = .Call('R_swig_new_OptionalBool', t, PACKAGE='QuantLib');
  ans <- if (is.null(ans)) ans
  else new("_p_ext__optionalT_bool_t", ref=ans);
  
  reg.finalizer(ans@ref, delete_OptionalBool);
  ans
  
}

