`Period` <- function(...) {
  argtypes <- mapply(class, list(...));
  argv <- list(...);
  argc <- length(argtypes);
  f <- NULL;
# dispatch functions 4
  if (argc == 0) {
    f <- Period__SWIG_0; 
  } else if (argc == 1) {
    if ( is.character(argv[[1]]) && length(argv[[1]]) == 1 ) {
      f <- Period__SWIG_2; 
    }
    else if ( is.character(argv[[1]]) && length(argv[[1]]) == 1 ) {
      f <- Period__SWIG_3; 
    }
  } else if (argc == 2) {
    if (( (is.integer(argv[[1]]) || is.numeric(argv[[1]])) && length(argv[[1]]) == 1 ) && ( is.character(argv[[2]]) && length(argv[[2]]) == 1 )) {
      f <- Period__SWIG_1; 
    }
  };
  if (is.null(f)) {
    stop("cannot find overloaded function for Period with argtypes (",toString(argtypes),")");
  };
  f(...);
}

