  argtypes <- mapply(class, list(...));
  argv <- list(...);
  argc <- length(argtypes);
  f <- NULL;
# dispatch functions 4
  if (argc == 0) {
    f <- DateVector__SWIG_0; 
  } else if (argc == 1) {
    if ( (is.integer(argv[[1]]) || is.numeric(argv[[1]])) && length(argv[[1]]) == 1 ) {
      f <- DateVector__SWIG_2; 
    }
    else if ( extends(argtypes[1], '_p_std__vectorT_Date_t') && length(argv[[1]]) == 1 ) {
      f <- DateVector__SWIG_1; 
    }
  } else if (argc == 2) {
    if (( (is.integer(argv[[1]]) || is.numeric(argv[[1]])) && length(argv[[1]]) == 1 ) && ( extends(argtypes[2], '_p_Date') && length(argv[[2]]) == 1 )) {
      f <- DateVector__SWIG_3; 
    }
  };
  if (is.null(f)) {
    stop("cannot find overloaded function for DateVector with argtypes (",toString(argtypes),")");
  };
  f(...);
}

