`ConvexMonotone` <- function(...) {
  argtypes <- mapply(class, list(...));
  argv <- list(...);
  argc <- length(argtypes);
  f <- NULL;
# dispatch functions 4
  if (argc == 0) {
    f <- ConvexMonotone__SWIG_3; 
  } else if (argc == 1) {
    if ( is.numeric(argv[[1]]) && length(argv[[1]]) == 1 ) {
      f <- ConvexMonotone__SWIG_2; 
    }
  } else if (argc == 2) {
    if (( is.numeric(argv[[1]]) && length(argv[[1]]) == 1 ) && ( is.numeric(argv[[2]]) && length(argv[[2]]) == 1 )) {
      f <- ConvexMonotone__SWIG_1; 
    }
  } else if (argc == 3) {
    if (( is.numeric(argv[[1]]) && length(argv[[1]]) == 1 ) && ( is.numeric(argv[[2]]) && length(argv[[2]]) == 1 ) && ( is.logical(argv[[3]]) && length(argv[[3]]) == 1 )) {
      f <- ConvexMonotone__SWIG_0; 
    }
  };
  if (is.null(f)) {
    stop("cannot find overloaded function for ConvexMonotone with argtypes (",toString(argtypes),")");
  };
  f(...);
}

