    else if ( extends(argtypes[1], '_p_std__vectorT_ext__shared_ptrT_StochasticProcess_t_t') && length(argv[[1]]) == 1 ) {
      f <- StochasticProcessVector__SWIG_1; 
    }
  } else if (argc == 2) {
    if (( (is.integer(argv[[1]]) || is.numeric(argv[[1]])) && length(argv[[1]]) == 1 ) && ((extends(argtypes[2], '_p_StochasticProcess') && length(argv[[2]]) == 1) || is.null(argv[[2]]))) {
      f <- StochasticProcessVector__SWIG_3; 
    }
  };
  if (is.null(f)) {
    stop("cannot find overloaded function for StochasticProcessVector with argtypes (",toString(argtypes),")");
  };
  f(...);
}

