`HestonProcess` <- function(...) {
  argtypes <- mapply(class, list(...));
  argv <- list(...);
  argc <- length(argtypes);
  f <- NULL;
# dispatch functions 2
  if (argc == 8) {
    if (( extends(argtypes[1], '_p_HandleT_YieldTermStructure_t') && length(argv[[1]]) == 1 ) && ( extends(argtypes[2], '_p_HandleT_YieldTermStructure_t') && length(argv[[2]]) == 1 ) && ( extends(argtypes[3], '_p_HandleT_Quote_t') && length(argv[[3]]) == 1 ) && ( is.numeric(argv[[4]]) && length(argv[[4]]) == 1 ) && ( is.numeric(argv[[5]]) && length(argv[[5]]) == 1 ) && ( is.numeric(argv[[6]]) && length(argv[[6]]) == 1 ) && ( is.numeric(argv[[7]]) && length(argv[[7]]) == 1 ) && ( is.numeric(argv[[8]]) && length(argv[[8]]) == 1 )) {
      f <- HestonProcess__SWIG_1; 
