`InstrumentVector` <- function(...) {
  argtypes <- mapply(class, list(...));
  argv <- list(...);
  argc <- length(argtypes);
  f <- NULL;
# dispatch functions 4
  if (argc == 0) {
    f <- InstrumentVector__SWIG_0; 
  } else if (argc == 1) {
    if ( (is.integer(argv[[1]]) || is.numeric(argv[[1]])) && length(argv[[1]]) == 1 ) {
      f <- InstrumentVector__SWIG_2; 
    }
    else if ( extends(argtypes[1], '_p_std__vectorT_ext__shared_ptrT_Instrument_t_t') && length(argv[[1]]) == 1 ) {
      f <- InstrumentVector__SWIG_1; 
    }
  } else if (argc == 2) {
    if (( (is.integer(argv[[1]]) || is.numeric(argv[[1]])) && length(argv[[1]]) == 1 ) && ((extends(argtypes[2], '_p_Instrument') && length(argv[[2]]) == 1) || is.null(argv[[2]]))) {
      f <- InstrumentVector__SWIG_3; 
    }
