  if (inherits(exercise, "ExternalReference")) exercise = slot(exercise,"ref"); 
  ;ans = .Call('R_swig_new_VanillaOption', payoff, exercise, PACKAGE='QuantLib');
  ans <- if (is.null(ans)) ans
  else new("_p_VanillaOption", ref=ans);
  
  reg.finalizer(ans@ref, delete_VanillaOption);
  ans
  
}

