`BatesEngine` <- function(...) {
  argtypes <- mapply(class, list(...));
  argv <- list(...);
  argc <- length(argtypes);
  f <- NULL;
# dispatch functions 3
  if (argc == 1) {
    if ((extends(argtypes[1], '_p_BatesModel') && length(argv[[1]]) == 1) || is.null(argv[[1]])) {
      f <- BatesEngine__SWIG_1; 
    }
  } else if (argc == 2) {
    if (((extends(argtypes[1], '_p_BatesModel') && length(argv[[1]]) == 1) || is.null(argv[[1]])) && ( (is.integer(argv[[2]]) || is.numeric(argv[[2]])) && length(argv[[2]]) == 1 )) {
      f <- BatesEngine__SWIG_0; 
    }
  } else if (argc == 3) {
    if (((extends(argtypes[1], '_p_BatesModel') && length(argv[[1]]) == 1) || is.null(argv[[1]])) && ( is.numeric(argv[[2]]) && length(argv[[2]]) == 1 ) && ( (is.integer(argv[[3]]) || is.numeric(argv[[3]])) && length(argv[[3]]) == 1 )) {
      f <- BatesEngine__SWIG_2; 
    }
  };
  if (is.null(f)) {
    stop("cannot find overloaded function for BatesEngine with argtypes (",toString(argtypes),")");
  };
  f(...);
}

