setMethod('$', '_p_FdmSchemeDesc', function(x, name)

{
  accessorFuns = list('type' = FdmSchemeDesc_type_get, 'theta' = FdmSchemeDesc_theta_get, 'mu' = FdmSchemeDesc_mu_get);
  vaccessors = c('type', 'theta', 'mu');
  ;        idx = pmatch(name, names(accessorFuns));
  if(is.na(idx)) 
  return(callNextMethod(x, name));
  f = accessorFuns[[idx]];
  if (is.na(match(name, vaccessors))) function(...){
    f(x, ...)
  } else f(x);
}


);
