  spread = as.numeric(spread);
  if (inherits(floatDayCount, "ExternalReference")) floatDayCount = slot(floatDayCount,"ref"); 
  intermediateCapitalExchange = as.logical(intermediateCapitalExchange);
  finalCapitalExchange = as.logical(finalCapitalExchange);
