  accessorFuns = list('overnightLegBPS' = OvernightIndexedSwap_overnightLegBPS, 'overnightLegNPV' = OvernightIndexedSwap_overnightLegNPV, 'paymentFrequency' = OvernightIndexedSwap_paymentFrequency, 'overnightIndex' = OvernightIndexedSwap_overnightIndex, 'overnightLeg' = OvernightIndexedSwap_overnightLeg, 'averagingMethod' = OvernightIndexedSwap_averagingMethod, 'lookbackDays' = OvernightIndexedSwap_lookbackDays, 'lockoutDays' = OvernightIndexedSwap_lockoutDays, 'applyObservationShift' = OvernightIndexedSwap_applyObservationShift);
  ;        idx = pmatch(name, names(accessorFuns));
  if(is.na(idx)) 
  return(callNextMethod(x, name));
  f = accessorFuns[[idx]];
  function(...){
    f(x, ...)
  };
}


);
# end of accessor method for OvernightIndexedSwap
setMethod('delete', '_p_OvernightIndexedSwap', function(obj) {delete_OvernightIndexedSwap(obj)})
