`MakeOIS` <- function(...) {
  argtypes <- mapply(class, list(...));
  argv <- list(...);
  argc <- length(argtypes);
  f <- NULL;
# dispatch functions 3
  if (argc == 2) {
    if (( extends(argtypes[1], '_p_Period') && length(argv[[1]]) == 1 ) && ((extends(argtypes[2], '_p_OvernightIndex') && length(argv[[2]]) == 1) || is.null(argv[[2]]))) {
      f <- MakeOIS__SWIG_2; 
    }
  } else if (argc == 3) {
    if (( extends(argtypes[1], '_p_Period') && length(argv[[1]]) == 1 ) && ((extends(argtypes[2], '_p_OvernightIndex') && length(argv[[2]]) == 1) || is.null(argv[[2]])) && (
        ((length(argv[[3]]) == 0) || (length(argv[[3]]) == 1 && is.numeric(argv[[3]])) || (length(argv[[3]]) == 1 && is.na(argv[[3]])))
        )) {
      f <- MakeOIS__SWIG_1; 
    }
  } else if (argc == 4) {
    if (( extends(argtypes[1], '_p_Period') && length(argv[[1]]) == 1 ) && ((extends(argtypes[2], '_p_OvernightIndex') && length(argv[[2]]) == 1) || is.null(argv[[2]])) && (
        ((length(argv[[3]]) == 0) || (length(argv[[3]]) == 1 && is.numeric(argv[[3]])) || (length(argv[[3]]) == 1 && is.na(argv[[3]])))
        ) && ( extends(argtypes[4], '_p_Period') && length(argv[[4]]) == 1 )) {
      f <- MakeOIS__SWIG_0; 
    }
  };
  if (is.null(f)) {
    stop("cannot find overloaded function for MakeOIS with argtypes (",toString(argtypes),")");
  };
  f(...);
}

