`BondFunctions_cleanPrice__SWIG_4` = function(bond, yield, dayCounter, compounding, frequency, settlementDate, .copy = FALSE)
{
  if (inherits(bond, "ExternalReference")) bond = slot(bond,"ref"); 
  
  if (inherits(dayCounter, "ExternalReference")) dayCounter = slot(dayCounter,"ref"); 
  compounding = enumToInteger(compounding, "_Compounding"); 
  
  if(length(compounding) > 1) {
    warning("using only the first element of compounding");
  };
  
  frequency = enumToInteger(frequency, "_Frequency"); 
  
  if(length(frequency) > 1) {
    warning("using only the first element of frequency");
  };
  
  if (inherits(settlementDate, "ExternalReference")) settlementDate = slot(settlementDate,"ref"); 
  ;.Call('R_swig_BondFunctions_cleanPrice__SWIG_4', bond, yield, dayCounter, compounding, frequency, settlementDate, as.logical(.copy), PACKAGE='QuantLib');
  
}

