`FdmBackwardSolver_rollback` = function(self, a, from, to, steps, dampingSteps)
{
  if (inherits(self, "ExternalReference")) self = slot(self,"ref"); 
  if (inherits(a, "ExternalReference")) a = slot(a,"ref"); 
  
  
  steps = as.integer(steps);
  
  if(length(steps) > 1) {
    warning("using only the first element of steps");
  };
  
  dampingSteps = as.integer(dampingSteps);
  
  if(length(dampingSteps) > 1) {
    warning("using only the first element of dampingSteps");
  };
  
  ;.Call('R_swig_FdmBackwardSolver_rollback', self, a, from, to, steps, dampingSteps, PACKAGE='QuantLib');
  
}

