`ExponentialForwardCorrelation` <- function(...) {
  argtypes <- mapply(class, list(...));
  argv <- list(...);
  argc <- length(argtypes);
  f <- NULL;
# dispatch functions 5
  if (argc == 1) {
    if ( is.numeric(argv[[1]]) ) {
      f <- ExponentialForwardCorrelation__SWIG_4; 
    }
  } else if (argc == 2) {
    if (( is.numeric(argv[[1]]) ) && ( is.numeric(argv[[2]]) && length(argv[[2]]) == 1 )) {
      f <- ExponentialForwardCorrelation__SWIG_3; 
    }
  } else if (argc == 3) {
    if (( is.numeric(argv[[1]]) ) && ( is.numeric(argv[[2]]) && length(argv[[2]]) == 1 ) && ( is.numeric(argv[[3]]) && length(argv[[3]]) == 1 )) {
      f <- ExponentialForwardCorrelation__SWIG_2; 
    }
  } else if (argc == 4) {
    if (( is.numeric(argv[[1]]) ) && ( is.numeric(argv[[2]]) && length(argv[[2]]) == 1 ) && ( is.numeric(argv[[3]]) && length(argv[[3]]) == 1 ) && ( is.numeric(argv[[4]]) && length(argv[[4]]) == 1 )) {
      f <- ExponentialForwardCorrelation__SWIG_1; 
    }
  } else if (argc == 5) {
    if (( is.numeric(argv[[1]]) ) && ( is.numeric(argv[[2]]) && length(argv[[2]]) == 1 ) && ( is.numeric(argv[[3]]) && length(argv[[3]]) == 1 ) && ( is.numeric(argv[[4]]) && length(argv[[4]]) == 1 ) && ( is.numeric(argv[[5]]) )) {
      f <- ExponentialForwardCorrelation__SWIG_0; 
    }
  };
  if (is.null(f)) {
    stop("cannot find overloaded function for ExponentialForwardCorrelation with argtypes (",toString(argtypes),")");
  };
  f(...);
}

