`HestonSLVProcess` <- function(...) {
  argtypes <- mapply(class, list(...));
  argv <- list(...);
  argc <- length(argtypes);
  f <- NULL;
# dispatch functions 2
  if (argc == 2) {
    if (((extends(argtypes[1], '_p_HestonProcess') && length(argv[[1]]) == 1) || is.null(argv[[1]])) && ((extends(argtypes[2], '_p_LocalVolTermStructure') && length(argv[[2]]) == 1) || is.null(argv[[2]]))) {
      f <- HestonSLVProcess__SWIG_1; 
    }
  } else if (argc == 3) {
    if (((extends(argtypes[1], '_p_HestonProcess') && length(argv[[1]]) == 1) || is.null(argv[[1]])) && ((extends(argtypes[2], '_p_LocalVolTermStructure') && length(argv[[2]]) == 1) || is.null(argv[[2]])) && ( is.numeric(argv[[3]]) && length(argv[[3]]) == 1 )) {
      f <- HestonSLVProcess__SWIG_0; 
    }
  };
  if (is.null(f)) {
    stop("cannot find overloaded function for HestonSLVProcess with argtypes (",toString(argtypes),")");
  };
  f(...);
}

