  argtypes <- mapply(class, list(...));
  argv <- list(...);
  argc <- length(argtypes);
  f <- NULL;
# dispatch functions 4
  if (argc == 2) {
    if (( extends(argtypes[1], '_p_GenericSequenceStatisticsT_Statistics_t') || is.null(argv[[1]]) ) && ( extends(argtypes[2], '_p_Array') && length(argv[[2]]) == 1 )) {
      f <- MultipleStatistics_add__SWIG_3; 
    }
    else if (( extends(argtypes[1], '_p_GenericSequenceStatisticsT_Statistics_t') || is.null(argv[[1]]) ) && ( is.numeric(argv[[2]]) )) {
      f <- MultipleStatistics_add__SWIG_1; 
    }
  } else if (argc == 3) {
    if (( extends(argtypes[1], '_p_GenericSequenceStatisticsT_Statistics_t') || is.null(argv[[1]]) ) && ( extends(argtypes[2], '_p_Array') && length(argv[[2]]) == 1 ) && ( is.numeric(argv[[3]]) && length(argv[[3]]) == 1 )) {
      f <- MultipleStatistics_add__SWIG_2; 
    }
    else if (( extends(argtypes[1], '_p_GenericSequenceStatisticsT_Statistics_t') || is.null(argv[[1]]) ) && ( is.numeric(argv[[2]]) ) && ( is.numeric(argv[[3]]) && length(argv[[3]]) == 1 )) {
      f <- MultipleStatistics_add__SWIG_0; 
    }
  };
  if (is.null(f)) {
    stop("cannot find overloaded function for MultipleStatistics_add with argtypes (",toString(argtypes),")");
  };
  f(...);
}

